    # For every row or column with at least two marker cells, fill the spaces
    # between its first and last marker with color 2; retain all markers.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    from collections import Counter
    counts = Counter(v for row in out for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != bg and v != 2)
    for r in range(h):
        xs = [c for c in range(w) if out[r][c] == marker]
        if len(xs) >= 2:
            for c in range(min(xs), max(xs)+1):
                if out[r][c] == bg: out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if out[r][c] == marker]
        if len(ys) >= 2:
            for r in range(min(ys), max(ys)+1):
                if out[r][c] == bg: out[r][c] = 2
    return out
